-- Generated by kUML — schema for "LapisCloud"
-- Dialect: postgres

-- payment_term_days (V1.2.1 Zahlungs-Fundament): "Zahlungsziel" in days, read by
-- ContributionService.generateContributionsForPeriod to compute a newly generated contribution's
-- due_date -- see 01-contribution.kuml.kts file header "Welle V1.2.1".
CREATE TABLE membership_tier (
    id UUID NOT NULL PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    description VARCHAR(1000) NOT NULL,
    contribution_amount DECIMAL(12, 2) NOT NULL,
    billing_interval VARCHAR(9) NOT NULL,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    payment_term_days INT NOT NULL DEFAULT 14,
    CHECK (billing_interval IN ('MONTHLY', 'QUARTERLY', 'YEARLY'))
);

CREATE TABLE document_folder (
    id UUID NOT NULL PRIMARY KEY,
    name VARCHAR(200) NOT NULL,
    parent_folder_id UUID NULL
);

-- V0.4.1 Serienbrief/PDF engine: the issuing association's own letterhead/bank/Gemeinnuetzigkeit
-- data. Exactly one row by convention (see 11-organization-settings.kuml.kts file header) --
-- seeded unconditionally below (not via DevSeedData, which is opt-in/demo-gated and must never
-- gate a real capability like letterhead data existing at all).
-- postal_mail_enabled (V0.4.2): explicit opt-in gate for Letterxpress postal-mail dispatch, see
-- that column's comment in 11-organization-settings.kuml.kts -- AVV requirement.
-- politician_ranking_enabled (V0.6.4): explicit opt-in gate for the Politiker-Profile/-Ranking
-- feature, see that column's comment in 11-organization-settings.kuml.kts.
-- auction_enabled / auction_max_value_ltr (V0.6.2): explicit opt-in gate (settable ONLY via
-- AuctionService.enableAuction/disableAuction, never via updateOrganizationSettings) and optional
-- ADMIN-configured per-listing LTR value cap -- see 21-auction.kuml.kts file header.
-- sepa_debit_enabled / payment_gateway_enabled / payment_gateway_provider (V1.2.1 Zahlungs-
-- Fundament): explicit opt-in gates, same "settable ONLY via the disclaimer-acknowledgment RPC,
-- never via updateOrganizationSettings" treatment as auction_enabled above -- see
-- 11-organization-settings.kuml.kts file header "Welle V1.2.1". payment_bank_account_id /
-- payment_fee_account_id / contribution_income_account_id: ordinary ADMIN-writable configuration
-- (which ledger_account a manually marked-paid contribution books into), FK added below (ledger_
-- account is declared later in this file).
CREATE TABLE organization_settings (
    id UUID NOT NULL PRIMARY KEY,
    name VARCHAR(300) NOT NULL,
    street VARCHAR(200) NULL,
    postal_code VARCHAR(20) NULL,
    city VARCHAR(200) NULL,
    country VARCHAR(100) NULL,
    bank_iban VARCHAR(34) NULL,
    bank_bic VARCHAR(11) NULL,
    tax_exemption_authority VARCHAR(300) NULL,
    tax_exemption_date DATE NULL,
    is_political_party BOOLEAN NOT NULL DEFAULT FALSE,
    postal_mail_enabled BOOLEAN NOT NULL DEFAULT FALSE,
    politician_ranking_enabled BOOLEAN NOT NULL DEFAULT FALSE,
    auction_enabled BOOLEAN NOT NULL DEFAULT FALSE,
    auction_max_value_ltr DECIMAL(18, 2) NULL,
    sepa_debit_enabled BOOLEAN NOT NULL DEFAULT FALSE,
    payment_gateway_enabled BOOLEAN NOT NULL DEFAULT FALSE,
    payment_gateway_provider VARCHAR(8) NULL,
    payment_bank_account_id UUID NULL,
    payment_fee_account_id UUID NULL,
    contribution_income_account_id UUID NULL,
    sepa_creditor_id VARCHAR(35) NULL,
    sepa_creditor_name VARCHAR(70) NULL,
    sepa_prenotification_days INT NOT NULL DEFAULT 14,
    dunning_enabled BOOLEAN NOT NULL DEFAULT FALSE,
    CHECK (payment_gateway_provider IS NULL OR payment_gateway_provider IN ('PAYPAL', 'STRIPE', 'MANUAL')),
    CHECK (sepa_prenotification_days >= 1 AND sepa_prenotification_days <= 30)
);

CREATE TABLE committee (
    id UUID NOT NULL PRIMARY KEY,
    name VARCHAR(200) NOT NULL,
    type VARCHAR(16) NOT NULL,
    description VARCHAR(1000) NOT NULL,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    quorum_percent INTEGER NOT NULL DEFAULT 50,
    created_at TIMESTAMP NOT NULL,
    CHECK (type IN ('EXECUTIVE_BOARD', 'WORKING_GROUP', 'COMMISSION', 'OTHER', 'GENERAL_ASSEMBLY'))
);

CREATE TABLE cost_center (
    id UUID NOT NULL PRIMARY KEY,
    code VARCHAR(50) NOT NULL,
    name VARCHAR(200) NOT NULL,
    description VARCHAR(1000) NULL,
    active BOOLEAN NOT NULL DEFAULT TRUE
);

-- V0.5.1 §25 PartG donor identity for a non-member donor (see 10-accounting.kuml.kts file header).
CREATE TABLE external_donor (
    id UUID NOT NULL PRIMARY KEY,
    display_name VARCHAR(300) NOT NULL,
    donor_category VARCHAR(41) NOT NULL,
    street VARCHAR(200) NULL,
    postal_code VARCHAR(20) NULL,
    city VARCHAR(200) NULL,
    country VARCHAR(100) NULL,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    CHECK (donor_category IN (
        'GERMAN_NATURAL_PERSON', 'EU_NATURAL_PERSON', 'NON_EU_FOREIGN_NATURAL_PERSON',
        'GERMAN_COMPANY_OR_ORGANIZATION', 'PUBLIC_LAW_CORPORATION', 'OVER_25_PERCENT_STATE_OWNED_COMPANY',
        'OTHER_PARTY_OR_PARLIAMENTARY_GROUP_ENTITY', 'PROFESSIONAL_OR_TRADE_ASSOCIATION', 'ANONYMOUS'
    ))
);

CREATE TABLE ledger_account (
    id UUID NOT NULL PRIMARY KEY,
    account_number VARCHAR(10) NOT NULL,
    name VARCHAR(200) NOT NULL,
    account_class INTEGER NOT NULL,
    type VARCHAR(9) NOT NULL,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    reserve_type VARCHAR(27) NULL,
    is_cash_register BOOLEAN NOT NULL DEFAULT FALSE,
    CHECK (type IN ('ASSET', 'LIABILITY', 'EQUITY', 'INCOME', 'EXPENSE')),
    CHECK (reserve_type IN ('PROJEKTRUECKLAGE', 'FREIE_RUECKLAGE', 'WIEDERBESCHAFFUNGSRUECKLAGE', 'BETRIEBSMITTELRUECKLAGE'))
);

CREATE TABLE member (
    id UUID NOT NULL PRIMARY KEY,
    display_name VARCHAR(200) NOT NULL,
    email VARCHAR(320) NOT NULL UNIQUE,
    status VARCHAR(11) NOT NULL,
    joined_at DATE NOT NULL,
    anonymized_at TIMESTAMP NULL,
    street VARCHAR(200) NULL,
    postal_code VARCHAR(20) NULL,
    city VARCHAR(200) NULL,
    country VARCHAR(100) NULL,
    date_of_birth DATE NULL,
    nationality VARCHAR(100) NULL,
    membership_tier_id UUID NULL,
    -- V0.7.2 Beitritts-Workflow board-decision metadata. reviewed_by is genuinely
    -- self-referential (member -> member) -- deliberately no FK constraint, same treatment
    -- document_folder.parent_folder_id already gets (see 02-document.kuml.kts file header).
    reviewed_by UUID NULL,
    reviewed_at TIMESTAMP NULL,
    rejection_reason VARCHAR(1000) NULL,
    -- V0.11.0 FRIEND self-registration. friend_since is set once on FRIEND self-registration and
    -- NEVER cleared. email_verified_at stays NULL unless LAPIS_FRIEND_REQUIRE_EMAIL_VERIFICATION
    -- is enabled and the member consumed a verification token (see friend_email_verification_token
    -- in 23-registration.kuml.kts).
    friend_since DATE NULL,
    email_verified_at TIMESTAMP NULL,
    CONSTRAINT chk_member_status CHECK (status IN ('APPLICATION', 'ACTIVE', 'GUEST', 'WITHDRAWN', 'REJECTED', 'FRIEND'))
);

CREATE TABLE account (
    id UUID NOT NULL PRIMARY KEY,
    password_hash VARCHAR(200) NULL,
    oidc_subject VARCHAR(200) NULL,
    role VARCHAR(9) NOT NULL,
    member_id UUID NOT NULL,
    CHECK (role IN ('MEMBER', 'BOARD', 'TREASURER', 'ADMIN'))
);

-- status (V1.2.1 Zahlungs-Fundament): widened VARCHAR(7)->VARCHAR(15) for the four new literals
-- (DEBIT_SCHEDULED/DEBIT_SUBMITTED/RETURNED/IN_DUNNING) -- see 01-contribution.kuml.kts file header
-- "Welle V1.2.1". due_date/payment_method: new columns, see same file header. On this FRESH-DB
-- baseline both can be declared NOT NULL directly (no existing rows to backfill) -- V7__payments.sql
-- carries the equivalent two-step ADD COLUMN + backfill + SET NOT NULL for an already-migrated
-- instance (pdv2).
CREATE TABLE contribution (
    id UUID NOT NULL PRIMARY KEY,
    period_start DATE NOT NULL,
    period_end DATE NOT NULL,
    amount_due DECIMAL(12, 2) NOT NULL,
    status VARCHAR(15) NOT NULL,
    paid_at TIMESTAMP NULL,
    paid_amount DECIMAL(12, 2) NULL,
    note VARCHAR(1000) NULL,
    created_at TIMESTAMP NOT NULL,
    member_id UUID NOT NULL,
    membership_tier_id UUID NOT NULL,
    due_date DATE NOT NULL,
    payment_method VARCHAR(12) NOT NULL DEFAULT 'MANUAL',
    -- sepa_mandate_id (V1.2.2 SEPA-Lastschriftmandate): deliberately NO inline FK here -- sepa_mandate
    -- is a genuinely new table that lives ONLY in V8__sepa_mandates.sql (never folded into this
    -- baseline, same V4-V7 precedent for brand-new tables), so on a truly fresh DB this column would
    -- reference a not-yet-existing table if the FK were declared inline. V8 adds the FK constraint
    -- once sepa_mandate exists (it creates that table earlier in its own script).
    sepa_mandate_id UUID NULL,
    CHECK (status IN ('OPEN', 'PAID', 'WAIVED', 'OVERDUE', 'DEBIT_SCHEDULED', 'DEBIT_SUBMITTED', 'RETURNED', 'IN_DUNNING')),
    CHECK (payment_method IN ('MANUAL', 'SEPA_DEBIT', 'GATEWAY'))
);

CREATE TABLE document (
    id UUID NOT NULL PRIMARY KEY,
    folder_id UUID NOT NULL,
