ALTER TABLE mailing_list ADD CONSTRAINT fk_mailing_list_created_by FOREIGN KEY (created_by) REFERENCES member(id);
ALTER TABLE mailing_list_subscription ADD CONSTRAINT fk_mailing_list_subscription_mailing_list_id FOREIGN KEY (mailing_list_id) REFERENCES mailing_list(id);
