    ADD CONSTRAINT fk_oidc_guest_profile_member_id FOREIGN KEY (member_id) REFERENCES member(id);

-- V0.8.3 Trust-Anchor-Governance: a deliberately-scoped, single-level CORE subset of OpenID
-- Federation 1.0 (RFC 9678), layered on top of the OIDC-guest-federation block above. See
-- 26-trust-anchor.kuml.kts file header for the full fachlich model, the "UX comfort, not a
-- security mechanism" framing, and why revocation needs more than expiry alone.

CREATE TABLE trust_anchor_signing_key (
    id UUID PRIMARY KEY,
    kid VARCHAR(64) NOT NULL UNIQUE,
    public_key_pem TEXT NOT NULL,
    private_key_pem TEXT NOT NULL,
    status VARCHAR(8) NOT NULL CHECK (status IN ('ACTIVE', 'RETIRED', 'REVOKED')),
    created_at TIMESTAMP NOT NULL,
    retired_at TIMESTAMP,
    revoked_at TIMESTAMP
);
CREATE INDEX idx_trust_anchor_signing_key_status ON trust_anchor_signing_key (status);
-- Deliberately NO seed INSERT here -- same reasoning as federation_actor_key/oidc_signing_key
-- above: TrustAnchorSigningKeyProvisioner inserts the first row (fixed sentinel id
-- '...-0000-0000000000f8', next unused slot after oidc_signing_key's own '...-f7') idempotently
-- on first Application.module() boot instead. Registered in
-- OrganizationRestoreService.SEEDED_SINGLETON_ROWS for the same "fresh restore target" reasoning
-- (UNLIKE federation_actor_key/oidc_signing_key, this table is rotation-capable -- more rows can
-- legitimately accumulate over a server's lifetime, which is correctly treated as "not a fresh
-- target" by that same pre-flight check, not a false positive).

CREATE TABLE trust_anchor_pool_member (
    id UUID PRIMARY KEY,
    home_server_uri VARCHAR(2048) NOT NULL UNIQUE,
    added_at TIMESTAMP NOT NULL
);

CREATE TABLE trusted_external_anchor (
    id UUID PRIMARY KEY,
    anchor_entity_uri VARCHAR(2048) NOT NULL UNIQUE,
    added_at TIMESTAMP NOT NULL
);

CREATE TABLE trust_anchor_event (
    id UUID PRIMARY KEY,
    occurred_at TIMESTAMP NOT NULL,
    event_type VARCHAR(22) NOT NULL CHECK (event_type IN
        ('KEY_PROVISIONED', 'KEY_ROTATED', 'KEY_REVOKED', 'POOL_MEMBER_ADDED', 'POOL_MEMBER_REMOVED',
         'TRUSTED_ANCHOR_ADDED', 'TRUSTED_ANCHOR_REMOVED')),
    subject VARCHAR(2048) NOT NULL
);
CREATE INDEX idx_trust_anchor_event_occurred_at ON trust_anchor_event (occurred_at);

-- V1.0 Videokonferenzen (Kleinsitzung), Wave 1 -- see 27-conference.kuml.kts file header for the
-- full fachlich model. livekit_room_name is the ONLY join key to LiveKit's own in-memory room
-- registry (server-generated `lc-<uuid4>`, never derived from title). conference_participation is
-- append-only per join (like `session`), not one row per (room, member) -- see file header.
-- allow_federation_guests (Wave 5 "Föderations-Gastbeitritt") is the per-room opt-in that gates
-- MemberStatus.GAST out of joinRoom, default FALSE -- see file header "Wave 5 addition".

CREATE TABLE conference_room (
    id UUID NOT NULL PRIMARY KEY,
    title VARCHAR(200) NOT NULL,
    description VARCHAR(1000) NOT NULL,
    livekit_room_name VARCHAR(64) NOT NULL,
    created_by_member_id UUID NOT NULL,
    created_at TIMESTAMP NOT NULL,
    ended_at TIMESTAMP NULL,
    max_participants INT NOT NULL,
    allow_federation_guests BOOLEAN NOT NULL DEFAULT FALSE,
    -- V1.0 Videokonferenzen, Wave 9 "Stream-Pause bei geheimen Abstimmungen" -- see
    -- 27-conference.kuml.kts file header "Wave 9 addition". NULL means not bound to any Sitzung.
    meeting_id UUID NULL
);
CREATE UNIQUE INDEX uq_conference_room_livekit_room_name ON conference_room (livekit_room_name);
CREATE INDEX idx_conference_room_created_by ON conference_room (created_by_member_id);
CREATE INDEX idx_conference_room_ended_at ON conference_room (ended_at);
CREATE INDEX idx_conference_room_meeting ON conference_room (meeting_id);

CREATE TABLE conference_participation (
    id UUID NOT NULL PRIMARY KEY,
    room_id UUID NOT NULL,
    member_id UUID NOT NULL,
    role VARCHAR(11) NOT NULL,
    joined_at TIMESTAMP NOT NULL,
    left_at TIMESTAMP NULL,
    CHECK (role IN ('MODERATOR', 'PARTICIPANT'))
);
CREATE INDEX idx_conference_participation_room ON conference_participation (room_id);
CREATE INDEX idx_conference_participation_member ON conference_participation (member_id);

-- Foreign Keys

ALTER TABLE conference_room ADD CONSTRAINT fk_conference_room_created_by_member_id FOREIGN KEY (created_by_member_id) REFERENCES member(id);
ALTER TABLE conference_room ADD CONSTRAINT fk_conference_room_meeting_id FOREIGN KEY (meeting_id) REFERENCES meeting(id);
ALTER TABLE conference_participation ADD CONSTRAINT fk_conference_participation_room_id FOREIGN KEY (room_id) REFERENCES conference_room(id);
ALTER TABLE conference_participation ADD CONSTRAINT fk_conference_participation_member_id FOREIGN KEY (member_id) REFERENCES member(id);

-- V1.0 Videokonferenzen (Kleinsitzung), Wave 2 "Aufzeichnung" -- see 28-conference-recording.kuml.kts
-- file header for the full fachlich model. Track Egress does not transcode: one raw file per
-- published track, hence conference_recording_track's one-row-per-egress shape;
-- conference_recording is the per-MEETING lifecycle record the eventual composed
-- document/document_version (Dokumentenablage, NOT a bespoke byte-storage column here) hangs off
-- of via the nullable document_id. status is a real, authoritative five-state machine
-- (RECORDING/STOPPING/PROCESSING/READY/FAILED) -- stopped_at/ready_at are denormalized display
-- timestamps, not the state machine's own source of truth.

CREATE TABLE conference_recording (
    id UUID NOT NULL PRIMARY KEY,
    room_id UUID NOT NULL,
    started_by_member_id UUID NOT NULL,
    started_at TIMESTAMP NOT NULL,
    stopped_at TIMESTAMP NULL,
    ready_at TIMESTAMP NULL,
    status VARCHAR(10) NOT NULL,
    access_level VARCHAR(14) NOT NULL,
    document_id UUID NULL,
    raw_dir VARCHAR(64) NOT NULL,
    duration_seconds BIGINT NULL,
    file_size_bytes BIGINT NULL,
    failure_reason VARCHAR(500) NULL,
    compose_attempts INT NOT NULL DEFAULT 0,
    CHECK (status IN ('RECORDING', 'STOPPING', 'PROCESSING', 'READY', 'FAILED')),
    CHECK (access_level IN ('PUBLIC_MEMBERS', 'BOARD_ONLY', 'ADMIN_ONLY'))
);
CREATE INDEX idx_conference_recording_room ON conference_recording (room_id);
CREATE INDEX idx_conference_recording_status ON conference_recording (status);
CREATE INDEX idx_conference_recording_started_by ON conference_recording (started_by_member_id);

CREATE TABLE conference_recording_track (
    id UUID NOT NULL PRIMARY KEY,
    recording_id UUID NOT NULL,
    egress_id VARCHAR(64) NOT NULL,
    livekit_track_id VARCHAR(64) NOT NULL,
    participant_identity VARCHAR(64) NOT NULL,
    track_source VARCHAR(19) NOT NULL,
    status VARCHAR(8) NOT NULL,
    started_at_epoch_nanos BIGINT NULL,
    ended_at_epoch_nanos BIGINT NULL,
    file_name VARCHAR(512) NULL,
    duration_ms BIGINT NULL,
    size_bytes BIGINT NULL,
    CHECK (track_source IN ('CAMERA', 'MICROPHONE', 'SCREEN_SHARE', 'SCREEN_SHARE_AUDIO', 'UNKNOWN')),
    CHECK (status IN ('STARTING', 'ACTIVE', 'COMPLETE', 'FAILED', 'ABORTED'))
);
CREATE UNIQUE INDEX uq_conference_recording_track_egress_id ON conference_recording_track (egress_id);
CREATE INDEX idx_conference_recording_track_recording ON conference_recording_track (recording_id);

-- Foreign Keys

ALTER TABLE conference_recording ADD CONSTRAINT fk_conference_recording_room_id FOREIGN KEY (room_id) REFERENCES conference_room(id);
ALTER TABLE conference_recording ADD CONSTRAINT fk_conference_recording_started_by_member_id FOREIGN KEY (started_by_member_id) REFERENCES member(id);
ALTER TABLE conference_recording ADD CONSTRAINT fk_conference_recording_document_id FOREIGN KEY (document_id) REFERENCES document(id);
ALTER TABLE conference_recording_track ADD CONSTRAINT fk_conference_recording_track_recording_id FOREIGN KEY (recording_id) REFERENCES conference_recording(id);

-- V1.0 Videokonferenzen (Kleinsitzung), Wave 3 "Externes Streaming" -- see
-- 29-conference-streaming.kuml.kts file header for the full fachlich model. Track Egress (Wave 2,
-- above) cannot do RTMP -- streaming needs a *composited* StartRoomCompositeEgress/
-- StartParticipantEgress request, hence a NEW table trio rather than a widening of
-- conference_recording/conference_recording_track. conference_stream_destination is this
-- codebase's first table with an at-rest-encrypted column (stream_key_ciphertext, AES-256-GCM via
-- network.lapis.cloud.server.crypto.SecretBox) -- the plaintext key is never stored, never
-- returned to any RPC caller. conference_stream.status is a real, authoritative six-state machine
-- (STARTING/LIVE/PAUSED/STOPPING/ENDED/FAILED); pause is StopEgress + PAUSED (LiveKit has no pause
-- primitive, verified live), resume is a fresh Start...Egress writing a NEW livekit_egress_id onto
-- the SAME row. conference_stream_target.url_fingerprint exists because LiveKit both redacts the
-- stream key in every URL it echoes back AND reorders stream_results relative to the request --
-- neither exact-URL nor array-index matching can associate a StreamInfo entry back to the target
-- row that started it, so this column is computed server-side at start time (LiveKit's own
-- redaction rule applied to the plaintext URL) and matched against on every StreamPoller tick.

CREATE TABLE conference_stream_destination (
    id UUID NOT NULL PRIMARY KEY,
    label VARCHAR(120) NOT NULL,
    platform VARCHAR(12) NOT NULL,
    rtmp_url VARCHAR(500) NOT NULL,
    stream_key_ciphertext VARCHAR(1024) NOT NULL,
    stream_key_set_at TIMESTAMP NOT NULL,
    created_by_member_id UUID NOT NULL,
    created_at TIMESTAMP NOT NULL,
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    CHECK (platform IN ('YOUTUBE', 'TWITCH', 'PEERTUBE', 'OWNCAST', 'GENERIC_RTMP'))
);
CREATE UNIQUE INDEX uq_conference_stream_destination_label ON conference_stream_destination (label);

CREATE TABLE conference_stream (
    id UUID NOT NULL PRIMARY KEY,
    room_id UUID NOT NULL,
    started_by_member_id UUID NOT NULL,
    status VARCHAR(8) NOT NULL,
    layout VARCHAR(19) NOT NULL,
    latency_mode VARCHAR(11) NOT NULL,
    participant_identity VARCHAR(64) NULL,
    livekit_egress_id VARCHAR(64) NULL,
    started_at TIMESTAMP NOT NULL,
    paused_at TIMESTAMP NULL,
    ended_at TIMESTAMP NULL,
    restart_count INT NOT NULL DEFAULT 0,
    failure_reason VARCHAR(500) NULL,
    -- V1.0 Videokonferenzen, Wave 9 "Stream-Pause bei geheimen Abstimmungen" -- see
    -- 29-conference-streaming.kuml.kts file header "Wave 9 addition".
    pause_reason VARCHAR(13) NULL,
    -- The status/pause_reason CHECKs are EXPLICITLY named (unlike layout/latency_mode below, left
    -- unnamed/untouched) so V2__conference_secret_ballot_stream_pause.sql can DROP CONSTRAINT IF
    -- EXISTS + re-ADD them idempotently on a fresh (test/dev) database that already has this widened
    -- CHECK from THIS file -- see that migration's own header comment for why both this baseline
    -- edit and a genuine V2 file exist side by side.
    CONSTRAINT chk_conference_stream_status CHECK (status IN ('STARTING', 'LIVE', 'PAUSED', 'STOPPING', 'ENDED', 'FAILED', 'PAUSING')),
    CHECK (layout IN ('GRID', 'SPEAKER', 'SINGLE_PARTICIPANT')),
    CHECK (latency_mode IN ('LOW_LATENCY', 'STANDARD')),
    CONSTRAINT chk_conference_stream_pause_reason CHECK (pause_reason IS NULL OR pause_reason IN ('MANUAL', 'SECRET_BALLOT'))
);
CREATE INDEX idx_conference_stream_room ON conference_stream (room_id);
CREATE INDEX idx_conference_stream_status ON conference_stream (status);

CREATE TABLE conference_stream_target (
    id UUID NOT NULL PRIMARY KEY,
    stream_id UUID NOT NULL,
    destination_id UUID NOT NULL,
    status VARCHAR(8) NOT NULL,
    url_fingerprint VARCHAR(255) NOT NULL,
    started_at_epoch_nanos BIGINT NULL,
    ended_at_epoch_nanos BIGINT NULL,
    retries INT NOT NULL DEFAULT 0,
    failure_reason VARCHAR(500) NULL,
    CHECK (status IN ('PENDING', 'ACTIVE', 'FINISHED', 'FAILED'))
);
CREATE INDEX idx_conference_stream_target_stream ON conference_stream_target (stream_id);

-- Foreign Keys

ALTER TABLE conference_stream_destination ADD CONSTRAINT fk_conference_stream_destination_created_by_member_id FOREIGN KEY (created_by_member_id) REFERENCES member(id);
ALTER TABLE conference_stream ADD CONSTRAINT fk_conference_stream_room_id FOREIGN KEY (room_id) REFERENCES conference_room(id);
ALTER TABLE conference_stream ADD CONSTRAINT fk_conference_stream_started_by_member_id FOREIGN KEY (started_by_member_id) REFERENCES member(id);
ALTER TABLE conference_stream_target ADD CONSTRAINT fk_conference_stream_target_stream_id FOREIGN KEY (stream_id) REFERENCES conference_stream(id);
ALTER TABLE conference_stream_target ADD CONSTRAINT fk_conference_stream_target_destination_id FOREIGN KEY (destination_id) REFERENCES conference_stream_destination(id);

-- V1.0 Videokonferenzen (Kleinsitzung), Wave 5 "Föderations-Gastbeitritt" -- see
-- 30-conference-guest-access.kuml.kts file header. Append-only, one row per GUEST join: the proof
-- that a federated OIDC guest was shown the current, versioned+hashed DSGVO consent text
-- (ConferenceGuestConsentDisclaimer) before joinRoom minted them a LiveKit token. Same
-- version/sha256 shape as auction_compliance_acknowledgment and
-- membership_agreement_acknowledgment, plus room_id (consent is per-room, per-join),
-- homeserver_url (snapshotted, because oidc_guest_profile.homeserver_url is overwritten on every
-- re-login), and organization_name (snapshotted for the identical reason -- organization_settings
-- .name is mutable, and a DSGVO Rechenschaftsnachweis must name the controller as it was presented
-- at consent time, not as it reads today -- design review D15).
--
-- V0.11.0: homeserver_url is now NULLable -- a FRIEND (self-registered, non-federated) has no home
-- server, but still writes this same acknowledgment row on every join (see MemberStatusSets
-- .NON_MEMBER). NULL means "non-member with no federated home server", not "unknown"/"pending".

CREATE TABLE conference_guest_consent_acknowledgment (
    id UUID NOT NULL PRIMARY KEY,
    member_id UUID NOT NULL,
    room_id UUID NOT NULL,
    acknowledged_at TIMESTAMP NOT NULL,
    consent_version VARCHAR(50) NOT NULL,
    consent_sha256 VARCHAR(64) NOT NULL,
    homeserver_url VARCHAR(2048) NULL,
    organization_name VARCHAR(300) NOT NULL
);
CREATE INDEX idx_conference_guest_consent_ack_member ON conference_guest_consent_acknowledgment (member_id);
CREATE INDEX idx_conference_guest_consent_ack_room ON conference_guest_consent_acknowledgment (room_id);

-- Foreign Keys

ALTER TABLE conference_guest_consent_acknowledgment ADD CONSTRAINT fk_conference_guest_consent_ack_member_id FOREIGN KEY (member_id) REFERENCES member(id);
ALTER TABLE conference_guest_consent_acknowledgment ADD CONSTRAINT fk_conference_guest_consent_ack_room_id FOREIGN KEY (room_id) REFERENCES conference_room(id);

-- V1.0 Videokonferenzen (Kleinsitzung), Wave 6 "Breakout-Räume" -- see 31-conference-breakout.kuml.kts
-- file header for the full fachlich model. A breakout room is a REAL, separate LiveKit room (own
-- livekit_room_name, same lc-<uuid4>-shaped generation as conference_room, own prefix "lc-bo-" for
-- log/debug legibility) that exists only for the lifetime of one "batch" -- at most ONE open batch
-- (closed_at IS NULL) per parent_room_id at a time, enforced in
-- ConferenceBreakoutService.createBreakoutRooms, never at the DB level (same "authorization/
-- invariant enforcement lives in the service layer, not a DB constraint" posture every other
-- Conference table already takes). No independent moderator, no independent recording/streaming, no
-- independent guest-access toggle -- all of those stay anchored to conference_room; see
-- IConferenceBreakoutService KDoc.

CREATE TABLE conference_breakout_room (
    id UUID NOT NULL PRIMARY KEY,
    parent_room_id UUID NOT NULL,
    label VARCHAR(120) NOT NULL,
    livekit_room_name VARCHAR(64) NOT NULL,
    created_by_member_id UUID NOT NULL,
    created_at TIMESTAMP NOT NULL,
    closed_at TIMESTAMP NULL
);
CREATE UNIQUE INDEX uq_conference_breakout_room_livekit_room_name ON conference_breakout_room (livekit_room_name);
CREATE INDEX idx_conference_breakout_room_parent ON conference_breakout_room (parent_room_id);
CREATE INDEX idx_conference_breakout_room_closed_at ON conference_breakout_room (closed_at);

-- conference_breakout_assignment is APPEND-ONLY per assignment, exactly like conference_participation
-- (joined_at/left_at) and session (revoked_at) -- see 27-conference.kuml.kts file header "Liveness
-- via nullable timestamps". A member reassigned from breakout room A to B gets assigned_at=... on a
-- NEW row for B, recalled_at stamped on the OLD row for A (never upserted in place) -- this keeps a
-- legible per-member breakout history for the lifetime of one meeting. recalled_at is stamped by
-- THREE distinct paths: (a) ConferenceBreakoutService.recallAll (moderator-initiated, all rows of
-- the batch), (b) ConferenceBreakoutService.returnToMainRoom (self-service, the caller's own row
-- only -- mirrors leaveRoom's "closes only the caller's own" no-IDOR pattern), (c)
-- ConferenceBreakoutCoordinator.closeAllBreakoutRoomsForRoom (parent conference_room ended without
-- an explicit recall first -- see IConferenceService.endRoom's Wave 6 addition).

CREATE TABLE conference_breakout_assignment (
    id UUID NOT NULL PRIMARY KEY,
    breakout_room_id UUID NOT NULL,
    member_id UUID NOT NULL,
    assigned_at TIMESTAMP NOT NULL,
    recalled_at TIMESTAMP NULL
);
CREATE INDEX idx_conference_breakout_assignment_room ON conference_breakout_assignment (breakout_room_id);
CREATE INDEX idx_conference_breakout_assignment_member ON conference_breakout_assignment (member_id);
-- The authorization-critical query ("does member X hold an OPEN assignment to breakout room Y") is
-- covered by idx_conference_breakout_assignment_room combined with the recalled_at IS NULL
-- predicate -- no separate composite index needed at Kleinsitzung scale (<=25 participants per
-- room, <=20 breakout rooms per batch, see MAX_BREAKOUT_ROOMS).

-- Foreign Keys

ALTER TABLE conference_breakout_room ADD CONSTRAINT fk_conference_breakout_room_parent_room_id FOREIGN KEY (parent_room_id) REFERENCES conference_room(id);
ALTER TABLE conference_breakout_room ADD CONSTRAINT fk_conference_breakout_room_created_by_member_id FOREIGN KEY (created_by_member_id) REFERENCES member(id);
ALTER TABLE conference_breakout_assignment ADD CONSTRAINT fk_conference_breakout_assignment_room_id FOREIGN KEY (breakout_room_id) REFERENCES conference_breakout_room(id);
ALTER TABLE conference_breakout_assignment ADD CONSTRAINT fk_conference_breakout_assignment_member_id FOREIGN KEY (member_id) REFERENCES member(id);

